 * date it counts in no total, is not overdue and cannot be settled; from then on it is an OPEN claim like any other.
 */
export function deferred(c: Claim, today: string | null): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/** Whether a claim makes its person active: open (or pending) and dated within the 30 days up to and including today. */
export function activeOn(c: Claim, today: string | null): boolean {
  return isOpen(c) && today !== null && plusDays(today, -29) <= c.date && c.date <= today;
}

/** Whether a claim is overdue: open (or pending), not deferred, and due by a date before the sheet's today. */
export function overdue(c: Claim, today: string | null): boolean {
  return isOpen(c) && today !== null && !deferred(c, today) && c.dueBy < today;
}

/** The floor in force on a date. */
export type FloorOn = (date: string) => string;

/**
 * What the late charge follows: the sheet's today and the late percent in force on a date; and the policy
 * date in force (the sheet's today when the setting is blank), which decides how a claim's live figures round.
 */
export interface Lateness {
  today: string | null;
  latePct: (date: string) => string;
  policyDate: string | null;
}

/** The whole days from one date (yyyy-mm-dd) to another. */
function daysBetween(from: string, to: string): number {
  const utc = (d: string) => {
    const [y, m, day] = d.split('-').map(Number);
    return Date.UTC(y, m - 1, day);
  };
  return Math.round((utc(to) - utc(from)) / 86_400_000);
}

/** The date (yyyy-mm-dd) the given whole days after another. */
export function plusDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/**
 * The due a claim shows and totals: a settled claim's frozen due; else its live due, the greater of the floor in
 * force on its date and its figure plus the late charge: for an overdue claim, for each full 30 days it is overdue,
 * the late percent in force on that boundary date (its due-by plus 30, 60, 90 ... days) of the figure, rounded like
 * the claim; a boundary whose percent is 0.00 adds nothing. Neither the charge nor the floor is bound by a
 * statement. A correction has neither.
 */
  protected readonly bulkGraded = signal<number | null>(null);
  protected readonly bulkGradeError = signal<string | null>(null);
  private bulkGrading = false;
  // The claims that count in the live totals: open, pending and settled ones, leaving out the open and pending ones
  // dated within one of their person's holds, or whose person's retirement date today has reached, that no statement
  // binds, and the deferred ones.
  protected readonly liveClaims = computed(() => {
    const leftOut = this.leftOut();
    return this.claims().filter((c) => counts(c) && !leftOut(c));
  });
  // Whether the live rules leave the claim out whatever its status: deferred, or open, bound by no statement and
  // dated within one of its person's holds or with its person's retirement date reached today.
  private readonly leftOut = computed(() => {
    const today = this.session.sheetToday();
    const holds = new Map(this.people().map((p) => [p.id, p.holds]));
    const retiredFrom = new Map(this.people().map((p) => [p.id, p.retiredFrom]));
    // a person whose retirement date the sheet's today has reached holds every claim, as a hold would
    const held = (c: Claim) => {
      const from = retiredFrom.get(c.personId) ?? null;
      return (from !== null && today !== null && today >= from)
        || (holds.get(c.personId) ?? []).some((h) => h.from <= c.date && (h.to === null || c.date <= h.to));
    };
